How do I order tasks that depend on each other?

```python
from collections import deque

deps = {"deploy": ["test", "build"], "test": ["build"], "build": ["lint"], "lint": []}

def topo(deps):
    indeg = {k: 0 for k in deps}
    for k, ds in deps.items():
        for d in ds:
            indeg.setdefault(d, 0)
    users = {k: [] for k in indeg}
    for k, ds in deps.items():
        for d in ds:
            users[d].append(k)
            indeg[k] += 1
    q = deque(sorted(k for k, n in indeg.items() if n == 0))
    order = []
    while q:
        n = q.popleft()
        order.append(n)
        for u in sorted(users[n]):
            indeg[u] -= 1
            if indeg[u] == 0:
                q.append(u)
    if len(order) != len(indeg):
        raise ValueError("cycle detected")
    return order

print(topo(deps))
