import hashlib

class Bloom:
    def __init__(self, bits=256, hashes=3):
        self.bits, self.k, self.v = bits, hashes, 0
    def _idx(self, item):
        for i in range(self.k):
            h = hashlib.sha256(f"{i}:{item}".encode()).digest()
