Implement a binary heap in Java to understand how PriorityQueue works.

```java
import java.util.*;

public class Main {
    static class MinHeap {
        private final List<Integer> a = new ArrayList<>();
        void add(int x) {
            a.add(x);
            int i = a.size() - 1;
            while (i > 0 && a.get((i - 1) / 2) > a.get(i)) {
                Collections.swap(a, i, (i - 1) / 2);
                i = (i - 1) / 2;
            }
        }
        int poll() {
            int top = a.get(0);
            int last = a.remove(a.size() - 1);
            if (!a.isEmpty()) {
                a.set(0, last);
                int i = 0;
                while (true) {
                    int l = 2 * i + 1, r = l + 1, m = i;
                    if (l < a.size() && a.get(l) < a.get(m)) m = l;
                    if (r < a.size() && a.get(r) < a.get(m)) m = r;
                    if (m == i) break;
                    Collections.swap(a, i, m);
                    i = m;
                }
            }
            return top;
        }
        boolean isEmpty() { return a.isEmpty(); }
    }

    public static void main(String[] args) {
        MinHeap h = new MinHeap();
        for (int x : new int[]{5, 3, 8, 1, 9, 2}) h.add(x);
        StringBuilder sb = new StringBuilder();
        while (!h.isEmpty()) sb.append(h.poll()).append(" ");
        System.out.println(sb.toString().trim());
    }
}
